window.S17Page={"sceneId":"r2","caseId":"s17x-r2-fcc-product-yields","name":"催化裂化产物预测","title":"催化裂化产物预测：一百公斤原料去了哪里","summary":"FCC把重分子转化成更轻的产品。用六项收率账看清原料与操作的影响，再用多输出回归预测整套产品组成。","directory":"expansion-cases","caseVersion":"1.2.0","portalHref":"../../../../portal/index.html","referenceHref":"../../../../portal/reference/fluorescence.html"};
(function(g){'use strict';const mean=a=>a.reduce((s,v)=>s+v,0)/a.length;const names=['干气','液化气','汽油','柴油','油浆','焦炭'];
function solve(A,b){let m=A.map((r,i)=>r.slice().concat(b[i]));for(let k=0;k<b.length;k++){let q=k;for(let i=k+1;i<b.length;i++)if(Math.abs(m[i][k])>Math.abs(m[q][k]))q=i;[m[q],m[k]]=[m[k],m[q]];let z=m[k][k];for(let j=k;j<=b.length;j++)m[k][j]/=z;for(let i=0;i<b.length;i++)if(i!==k){let d=m[i][k];for(let j=k;j<=b.length;j++)m[i][j]-=d*m[k][j];}}return m.map(r=>r[b.length]);}
const features=x=>{let t=(x.temperature-525)/25,c=(x.ratio-6)/2,d=(x.density-920)/40;return[1,t,c,d,t*t,c*c,t*c,t*d];};
function project(y){let a=y.map(v=>Math.max(0,v)),sum=a.reduce((s,v)=>s+v,0);return a.map(v=>100*v/sum);}
function fit(rows){let n=8,A=Array.from({length:n},()=>Array(n).fill(0)),B=Array.from({length:6},()=>Array(n).fill(0));rows.forEach(r=>{let z=features(r.x);for(let j=0;j<n;j++){for(let k=0;k<n;k++)A[j][k]+=z[j]*z[k];r.y.forEach((v,h)=>B[h][j]+=z[j]*v);}});for(let j=1;j<n;j++)A[j][j]+=.001;return B.map(b=>solve(A,b));}
function predict(model,x){let z=features(x);return project(model.map(c=>c.reduce((s,v,i)=>s+v*z[i],0)));}
function generate(){return Array.from({length:180},(_,i)=>{let t=((i*43)%179)/178*2-1,c=((i*79+11)%179)/178*2-1,d=((i*113+35)%179)/178*2-1,x={temperature:525+25*t,ratio:6+2*c,density:920+40*d},n=.18*Math.sin(i*1.9),raw=[4+1.3*t+.4*c+.25*t*t,16+2*t+1.2*c-.6*d,46+3*t+2*c-1.6*t*t-1.2*d+n,20-3*t-1.5*c+.6*d,8-2.4*t-2*c+1.6*d,6+.8*t+.9*c+.9*d+.4*t*c];return{id:'FCC-'+String(i+1).padStart(3,'0'),x,y:project(raw),split:i<126?'train':'test',feedClass:d<0?'轻质原料':'重质原料'};});}
function run(params={}){let cfg={temperature:525,ratio:6,density:920,...params},rows=generate(),train=rows.filter(r=>r.split==='train'),test=rows.filter(r=>r.split==='test'),model=fit(train),groupMeans={};for(let k of ['轻质原料','重质原料'])groupMeans[k]=names.map((_,j)=>mean(train.filter(r=>r.feedClass===k).map(r=>r.y[j])));let predictions=test.map(r=>({id:r.id,x:r.x,prediction:predict(model,r.x),baseline:groupMeans[r.feedClass],truth:r.y})),metrics=names.map((name,j)=>({name,n:test.length,mae:mean(predictions.map(r=>Math.abs(r.prediction[j]-r.truth[j]))),baselineMAE:mean(predictions.map(r=>Math.abs(r.baseline[j]-r.truth[j])))}));return{sceneId:'r2',params:cfg,names,dataNature:'独立批次教学合成，六项收率包含焦炭，质量基准%',split:{train:126,test:54,unit:'独立原料—操作批次'},model,groupMeans,prediction:predict(model,cfg),baseline:groupMeans[cfg.density<920?'轻质原料':'重质原料'],predictions,metrics,sensitivity:Array.from({length:26},(_,i)=>{let temperature=500+i*2;return{temperature,y:predict(model,{...cfg,temperature})};}),closure:Math.abs(predict(model,cfg).reduce((s,v)=>s+v,0)-100)};}
g.R2Core={names,features,project,fit,predict,generate,run};})(globalThis);

